import{_ as s,a0 as p,w as m,s as i,ao as l,I as n,x as t,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"彭博社开源 Memray，一个 Python 内存剖析器 | LCTT x X-CMD","titleTemplate":false,"description":"彭博社开源 Memray，一个 Python 内存剖析器 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"彭博社开源 Memray，一个 Python 内存剖析器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"彭博社开源 Memray，一个 Python 内存剖析器 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220427 Bloomberg Open Sources Memray, A Python Memory Profiler","title":"彭博社开源 Memray，一个 Python 内存剖析器","tag":"202205","desc":""},"relativePath":"202205/20220427 Bloomberg Open Sources Memray, A Python Memory Profiler.md","filePath":"[post].md"}'),y={name:"202205/20220427 Bloomberg Open Sources Memray, A Python Memory Profiler.md"};function u(d,e,h,f,g,b){const o=p("Link");return m(),i("div",null,[e[15]||(e[15]=l(`<h1 id="彭博社开源-memray-一个-python-内存剖析器" tabindex="-1">彭博社开源 Memray，一个 Python 内存剖析器 <a class="header-anchor" href="#彭博社开源-memray-一个-python-内存剖析器" aria-label="Permalink to “彭博社开源 Memray，一个 Python 内存剖析器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/12/081556a84j8f331irlszo2.jpg" alt=""></p><p>Memray 是一个由彭博社开发的<ruby>内存剖析器<rt>memory profiler</rt></ruby>，现在已经开源。它可以跟踪 Python 代码中的内存分配，包括本地扩展和 Python 解释器本身。内存剖析是了解程序如何利用内存的有力工具，因此可以检测内存泄漏或确定程序中哪些区域消耗的内存最多。</p><p>与 py-spy 等抽样内存剖析器相比，Memray 可以跟踪每个函数调用，包括对 C/C++ 库的调用，并详细显示调用栈。彭博社称，这并不以牺牲性能为代价，剖析只使解释代码的速度变慢一点。然而，原生代码剖析的速度较慢，因此需要直接启用。</p><p>Memray 可以根据获得的内存消耗数据生成各种报告，包括火焰图，这对快速、准确地识别最常见的代码路径很有价值。</p><p>据 EgdeDB 的联合创始人兼 CEO Yury Selivanov 称，该工具提供了以前无法获得的对 Python 应用的洞察力。Memray 可以用来从命令行中执行和剖析 Python 应用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 -m memray run -o output.bin my_script.py</span></span>
<span class="line"><span>$ python3 -m memray flamegraph output.bin</span></span></code></pre></div><p>另外，你可以使用 pytest-memray 将 Memray 集成到你的测试套件中。你也可以用 <code>-native</code> 命令行选项对所有的 C/C++ 调用进行剖析，或者用 <code>-live</code> 命令行选项在程序执行过程中实时分析内存分配。Memray 可以在 Linux x86/64 系统上用 <code>python3 -m pip install memray</code> 来安装。</p><p>（题图由 Frantisek Krejci 在 Pixabay 上发布）</p><hr>`,10)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/04/bloomberg-open-sources-memray-a-python-memory-profiler/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/04/bloomberg-open-sources-memray-a-python-memory-profiler/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:a(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const T=s(y,[["render",u]]);export{C as __pageData,T as default};
